/// List all available `(layout, variant)` pairs from the static registry.
/// Returns pairs suitable for `WKB::new_from_names`. The base layout has an
/// empty variant string.
pub fn list_layouts() -> Vec<(String, String)> {
    LAYOUTS
        .iter()
        .map(|&(layout, variant)| (layout.to_string(), variant.to_string()))
        .collect()
}

/// Get all available layout variants for a given locale (test utility).
pub fn get_all_layouts_for_locale(locale: &str) -> Vec<String> {
    let mut layouts: Vec<String> = LAYOUTS
        .iter()
        .filter(|&&(layout, _)| layout == locale)
        .map(|&(_, variant)| variant.to_string())
        .collect();
    if layouts.is_empty() {
        layouts.push(String::new());
    }
    layouts
}
